import json,re
async def grab(qq,kw,w=200,n=6):
    try:
        r=json.loads(await web_search({"query":qq}))
    except Exception as e:
        print("ERR",e);return
    print("##",qq)
    for x in r[:n]:
        c=x['content']; out=[]
        for k in kw:
            m=re.search(k,c)
            if m: out.append(c[m.start():m.start()+w].replace("\n"," "))
        if out:
            print(x['url']); [print("    ",o) for o in out]
await grab("Arista Networks 2025 annual revenue twelve months ended December 31 2025 income statement",["Total revenue[^A-Za-z]{0,80}","Revenue of \$9[^.]*"])
